from typing import List

class Solution:
    def countBits(self, n: int) -> List[int]:
        ans = [0] * (n + 1)
        for i in range(1, n + 1):
            # Drop the last bit, then add it back if it was 1.
            ans[i] = ans[i >> 1] + (i & 1)
        return ans

